#include "CadDocument.h"
#include "SketchGeometry.h"
#include "SketchAxis3d.h"
#include "SketchRotate.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <QUuid>
#include <cmath>
#include <iostream>
#include <numbers>
#include <stdexcept>
void check(bool v,const QString& s){if(!v)throw std::runtime_error(s.toStdString());}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{CadDocument doc;auto source=SketchGeometry::newFeature(doc.authored()["documentId"].toString(),"XY");const double xy[4][2]={{12,6},{32,10},{27,22},{9,18}};for(int n=0;n<4;++n)source=SketchGeometry::addLine(source,{{"u1Mm",xy[n][0]},{"v1Mm",xy[n][1]},{"u2Mm",xy[(n+1)%4][0]},{"v2Mm",xy[(n+1)%4][1]}});auto p=source["parameters"].toObject();auto points=p["points"].toArray();for(int n=0;n<5;++n){const int a=n<4?n:0,b=n<4?(n+1)%4:2;const auto r=SketchGeometry::addDimension(source,{{"kind","linear"},{"pointIds",QJsonArray{points[a].toObject()["id"],points[b].toObject()["id"]}},{"valueMm",std::hypot(xy[a][0]-xy[b][0],xy[a][1]-xy[b][1])},{"driving",true}});check(r.ok,r.error);source=r.feature;}p=SketchAxis3d::upsert(source["parameters"].toObject(),4,3,10);source["parameters"]=p;const auto axis=p["constructionLines3d"].toArray().first().toObject();QJsonArray ids;for(const auto& v:p["entities"].toArray())ids.append(v.toObject()["id"]);const auto before=SketchGeometry::evaluateFeature(source);

 const auto original=SketchGeometry::retainedRotate(source,{{"entityIds",ids},{"axisLineId",axis["id"]},{"angleDeg",30}});check(original.ok,original.error);const auto legacy=original.feature,legacyParams=legacy["parameters"].toObject();const auto group=legacyParams["rotateGroups"].toArray().first().toObject();check(!group.contains("sourceFrame"),"Legacy owner has no implicit frame");const auto unchanged=SketchGeometry::solveDraft(legacy);check(unchanged.ok && unchanged.feature==legacy,"Legacy evaluation does not migrate authored data");const auto dim=legacyParams["dimensions"].toArray().first().toObject();const auto sized=SketchGeometry::updateDimension(legacy,{{"dimensionId",dim["id"]},{"valueMm",22}});check(sized.ok,sized.error);const auto sp=sized.feature["parameters"].toObject(),sg=sp["rotateGroups"].toArray().first().toObject(),frame=sg["sourceFrame"].toObject();check(sg["id"]==group["id"] && sg["angleDeg"]==30 && sg["axisLineId"]==axis["id"],"Owner/angle/axis preserved");check(frame["version"]==1 && frame["anchorPointId"]==points[0].toObject()["id"] && frame["headingPointId"]==points[1].toObject()["id"] && frame["anchorUMm"]==12 && frame["anchorVMm"]==6,"Persistent source frame");check(std::abs(frame["headingAngleRad"].toDouble()-std::atan2(4.,20.))<1e-12,"Directed source heading");
 const double expected[4][2]={{12,6},{33.5727748652,10.3145549730},{27.3080799650,21.7054986481},{9.2337506509,18.0560302147}};
 auto verify=[&](const QJsonObject& f,double angle=30,double px=4,double py=3){const auto p=f["parameters"].toObject(),g=p["rotateGroups"].toArray().first().toObject();const auto s=g["sourcePoints"].toArray(),out=p["points"].toArray();for(int n=0;n<4;++n){check(s[n].toObject()["pointId"]==points[n].toObject()["id"],"Source point identity");for(int k=0;k<2;++k)check(std::abs(s[n].toObject()[k?"vMm":"uMm"].toDouble()-expected[n][k])<1e-6,"Independent analytic source solution");const double t=angle*std::numbers::pi/180,u=expected[n][0]-px,v=expected[n][1]-py;check(std::abs(out[n].toObject()["uMm"].toDouble()-(px+u*std::cos(t)-v*std::sin(t)))<1e-6 && std::abs(out[n].toObject()["vMm"].toDouble()-(py+u*std::sin(t)+v*std::cos(t)))<1e-6,"Single derived rotation of updated source");}check(g["sourceFrame"]==frame,"Source frame does not follow angle/pivot");const auto e=SketchGeometry::evaluateFeature(f);check(e.profiles.size()==1 && e.profiles[0].profileId==before.profiles[0].profileId,"Profile ID preserved");};verify(sized.feature);
 for(int n=0;n<3;++n){const auto r=SketchGeometry::solveDraft(sized.feature);check(r.ok && r.feature==sized.feature,"Framed evaluation is exactly idempotent: "+r.error);}const auto edited=SketchGeometry::retainedRotate(sized.feature,{{"groupId",group["id"]},{"axisLineId",axis["id"]},{"angleDeg",-15}});check(edited.ok,edited.error);verify(edited.feature,-15);auto pivot=sized.feature;pivot["parameters"]=SketchAxis3d::upsert(sp,6,5,12,axis["id"].toString());const auto ps=SketchGeometry::solveDraft(pivot);check(ps.ok,ps.error);verify(ps.feature,30,6,5);
 const auto distant=SketchGeometry::addStandalonePoint(source,{{"uMm",100},{"vMm",100}});check(distant.ok,distant.error);const auto dr=SketchGeometry::retainedRotate(distant.feature,{{"entityIds",ids},{"axisLineId",axis["id"]},{"angleDeg",30}});check(dr.ok,dr.error);const auto ds=SketchGeometry::updateDimension(dr.feature,{{"dimensionId",dim["id"]},{"valueMm",22}});check(ds.ok,ds.error);check(ds.feature["parameters"].toObject()["points"].toArray().last()==distant.feature["parameters"].toObject()["points"].toArray().last(),"Unselected source point exact");
 for(const auto& args:QJsonArray{QJsonObject{{"dimensionId",dim["id"]},{"valueMm",1}},QJsonObject{{"dimensionId",dim["id"]},{"valueMm",0}},QJsonObject{{"dimensionId",dim["id"]},{"valueMm",22},{"parameterId",QUuid::createUuid().toString(QUuid::WithoutBraces)}},QJsonObject{{"dimensionId",dim["id"]},{"expression","22 mm"},{"expressionUnits","mm"}}}){const auto r=SketchGeometry::updateDimension(sized.feature,args.toObject());check(!r.ok && r.feature==sized.feature,"Impossible/bound/expression resize refuses atomically");}
 for(int kind=0;kind<4;++kind){auto bad=sized.feature,p=sp,g=sg;auto sources=g["sourcePoints"].toArray(),dimensions=p["dimensions"].toArray();if(kind==0){auto d=dimensions[0].toObject();d["valueMm"]=23;dimensions[0]=d;p["dimensions"]=dimensions;}if(kind==1){auto s=sources[2].toObject();s["uMm"]=s["uMm"].toDouble()+1;sources[2]=s;g["sourcePoints"]=sources;}if(kind==2){auto f=frame;f["headingAngleRad"]=.4;g["sourceFrame"]=f;}p["rotateGroups"]=QJsonArray{g};if(kind==1)p=SketchRotate::materialize(SketchRotate::source(p),QJsonArray{g});if(kind==3){auto pts=p["points"].toArray();auto q=pts[0].toObject();q["uMm"]=q["uMm"].toDouble()+1;pts[0]=q;p["points"]=pts;}bad["parameters"]=p;check(!SketchGeometry::solveDraft(bad).ok,"Raw snapshot/source/frame/cache tampering refuses");}
 check(doc.commit(SketchGeometry::replaceFeature(doc.authored(),ps.feature),"Resize rotated source").isEmpty(),"Commit");const auto authored=doc.authored();doc.history().undo();doc.history().redo();check(doc.authored()==authored,"Exact history");QTemporaryDir dir;check(doc.save(dir.filePath("sized.alloy")).isEmpty(),"Save");CadDocument reopened;check(reopened.open(dir.filePath("sized.alloy")).isEmpty() && reopened.authored()==authored,"Exact authored reopen");std::cout<<"SKETCH_ROTATE_SOURCE_SIZE_CORE_OK\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
